		return nil, errors.New("pod doesn't belong to any service, pod:" + p.Name)
	}

	endpointList := make([]*servicev1.ServiceEndpoint, 0)
	var err error = nil

	if lrcConfig != nil {
		lrcSvc := lrcConfig.Spec.AtlasApplicationName
		if p.IP == "" {
			metrics.UpdatePodRegisterStatus(p.Namespace, p.Name, lrcSvc, metrics.PodRegisterStatusEmptyAddress)
			err = multierr.Append(err, errors.New("empty address found for endpoint, svc: "+lrcSvc))
			return endpointList, err
		}

		if value, ok := p.Annotations[utils.LegacyConsulRegisterEnabledAnnotation]; ok {
			enabled, err := strconv.ParseBool(value)
			if err != nil {
				log.Error().Dict("custom_attributes", logger.Attrs().
					Str("pod_name", p.Name).
					Str("pod_ip", p.IP).
					Str("annotation", utils.LegacyConsulRegisterEnabledAnnotation).
					Str("error", err.Error())).
					Msg("Cannot convert annotation value")
				return false
			}
			if !enabled {
				log.Debug().Msgf("Pod %s in %s namespace is disabled by annotation. Value %s", p.Name, p.Namespace, value)
				return false
			}
		} else {
			// We did not find the new or the legacy register annotation.
			// We will fall back to the default pod registration method.

			// Ensure the name is there
			if includeNamespaces[p.Namespace] {
				// Check if the pod is part of k8s service
				log.Debug().Msgf("checking in services sync map...")
				return isPodPartOfK8sService(p, k8sServices)
			} else {
				globalRegEnabled := global.IsClusterRegistrationEnabled()
				if !globalRegEnabled {
					return false
				}
			}

		}
	}

	log.Debug().Msgf("Pod %s is enabled for registration", p.Name)
	return true
}

// getRegistrationMethod returns the registration method for a pod.
// Returns empty string if pod is not enabled for registration.
// This is used for logging to distinguish between LRC and annotation-based registration.
func (c *Controller) getRegistrationMethod(podInfo *PodInfo) RegistrationMethod {
	ns := podInfo.Namespace
	excludedNamespaces := os.Getenv(utils.ExcludeNamespacesKey)
	namespaces := make([]string, 0)
	if excludedNamespaces != "" {
		namespaces = strings.Split(excludedNamespaces, ",")
	}
	namespaces = append(namespaces, utils.DefaultExcludedNamespaces...)
	for _, ens := range namespaces {
		regex, err := regexp.Compile(strings.TrimSpace(ens))
		if err != nil {
			continue
		}
		if regex.MatchString(ns) {
			return ""
		}
	}

	// Check for nexus annotation
	if value, ok := podInfo.Annotations[utils.NexusRegisterEnabledAnnotation]; ok {
		enabled, err := strconv.ParseBool(value)
		if err != nil || !enabled {
			return ""
		}
		return RegistrationMethodAnnotation
	}

	// Check for legacy consul annotation
	if value, ok := podInfo.Annotations[utils.LegacyConsulRegisterEnabledAnnotation]; ok {
		enabled, err := strconv.ParseBool(value)
		if err != nil || !enabled {
			return ""
		}
		return RegistrationMethodAnnotation
	}

	// Check if namespace is labeled for registration
	nsMap := *c.namespaces.Load()
	if nsMap[podInfo.Namespace] {
		svcs := *c.k8sServices.Load()
		if isPodPartOfK8sService(podInfo, svcs) {
			return RegistrationMethodK8sService
		}
		return ""
	}

